package com.example.starter.schedule.repository;

import com.example.starter.schedule.domain.ContactWindow;
import com.example.starter.schedule.domain.GroundStation;
import com.example.starter.schedule.domain.Satellite;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.simple.SimpleJdbcInsert;
import org.springframework.stereotype.Repository;

import java.time.Instant;
import java.util.List;
import java.util.Optional;

/**
 * 卫星、地面站、过境窗口等合成主数据访问。
 */
@Repository
public class MasterDataRepository {

    private final JdbcTemplate jdbc;
    private final SimpleJdbcInsert satelliteInsert;
    private final SimpleJdbcInsert stationInsert;
    private final SimpleJdbcInsert windowInsert;

    public MasterDataRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
        this.satelliteInsert = new SimpleJdbcInsert(jdbc)
                .withTableName("satellite").usingGeneratedKeyColumns("id");
        this.stationInsert = new SimpleJdbcInsert(jdbc)
                .withTableName("ground_station").usingGeneratedKeyColumns("id");
        this.windowInsert = new SimpleJdbcInsert(jdbc)
                .withTableName("contact_window").usingGeneratedKeyColumns("id");
    }

    private static final RowMapper<Satellite> SATELLITE_MAPPER = (rs, n) ->
            new Satellite(rs.getLong("id"), rs.getString("code"),
                    rs.getString("name"), rs.getTimestamp("created_at").toInstant());

    private static final RowMapper<GroundStation> STATION_MAPPER = (rs, n) ->
            new GroundStation(rs.getLong("id"), rs.getString("code"),
                    rs.getString("name"), rs.getTimestamp("created_at").toInstant());

    private static final RowMapper<ContactWindow> WINDOW_MAPPER = (rs, n) ->
            new ContactWindow(rs.getLong("id"), rs.getLong("satellite_id"),
                    rs.getLong("station_id"),
                    rs.getTimestamp("start_time").toInstant(),
                    rs.getTimestamp("end_time").toInstant(),
                    rs.getString("day_key"));

    public Optional<Satellite> findSatelliteByCode(String code) {
        return jdbc.query("SELECT id, code, name, created_at FROM satellite WHERE code = ?",
                SATELLITE_MAPPER, code).stream().findFirst();
    }

    public Satellite getSatelliteByCode(String code) {
        return findSatelliteByCode(code).orElseThrow();
    }

    public Optional<GroundStation> findStationByCode(String code) {
        return jdbc.query("SELECT id, code, name, created_at FROM ground_station WHERE code = ?",
                STATION_MAPPER, code).stream().findFirst();
    }

    public List<GroundStation> findAllStations() {
        return jdbc.query("SELECT id, code, name, created_at FROM ground_station ORDER BY id",
                STATION_MAPPER);
    }

    public Optional<ContactWindow> findWindowById(long windowId) {
        return jdbc.query("""
                        SELECT id, satellite_id, station_id, start_time, end_time, day_key
                        FROM contact_window WHERE id = ?""",
                WINDOW_MAPPER, windowId).stream().findFirst();
    }

    public List<ContactWindow> findWindows(long stationId, long satelliteId, String dayKey) {
        return jdbc.query("""
                        SELECT id, satellite_id, station_id, start_time, end_time, day_key
                        FROM contact_window
                        WHERE station_id = ? AND satellite_id = ? AND day_key = ?
                        ORDER BY start_time""",
                WINDOW_MAPPER, stationId, satelliteId, dayKey);
    }

    /**
     * 查询某卫星在某站某日、不早于给定时刻的全部预报窗口，按开始时刻升序。
     */
    public List<ContactWindow> findWindowsAfter(long stationId, long satelliteId,
                                                String dayKey, Instant notBefore) {
        return jdbc.query("""
                        SELECT id, satellite_id, station_id, start_time, end_time, day_key
                        FROM contact_window
                        WHERE station_id = ? AND satellite_id = ? AND day_key = ?
                          AND end_time > ?
                        ORDER BY start_time""",
                WINDOW_MAPPER, stationId, satelliteId, dayKey,
                java.sql.Timestamp.from(notBefore));
    }

    public long insertSatellite(String code, String name) {
        return satelliteInsert.executeAndReturnKey(
                new java.util.HashMap<>(java.util.Map.of("code", code, "name", name))).longValue();
    }

    public long insertStation(String code, String name) {
        return stationInsert.executeAndReturnKey(
                new java.util.HashMap<>(java.util.Map.of("code", code, "name", name))).longValue();
    }

    public long insertWindow(long satelliteId, long stationId,
                             Instant start, Instant end, String dayKey) {
        return windowInsert.executeAndReturnKey(new java.util.HashMap<>(java.util.Map.of(
                "satellite_id", satelliteId,
                "station_id", stationId,
                "start_time", java.sql.Timestamp.from(start),
                "end_time", java.sql.Timestamp.from(end),
                "day_key", dayKey
        ))).longValue();
    }
}

package com.example.starter.schedule.repository;

import com.example.starter.schedule.domain.ContactEvent;
import com.example.starter.schedule.domain.ContactReport;
import com.example.starter.schedule.model.EventType;
import com.example.starter.schedule.model.ReportStatus;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.simple.SimpleJdbcInsert;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.Optional;

/**
 * 执行回报与回报事件流水访问。
 * (station_id, window_id) 唯一约束保证“窗口＋站”去重。
 */
@Repository
public class ReportRepository {

    private final JdbcTemplate jdbc;
    private final SimpleJdbcInsert reportInsert;
    private final SimpleJdbcInsert eventInsert;

    public ReportRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
        this.reportInsert = new SimpleJdbcInsert(jdbc)
                .withTableName("contact_report").usingGeneratedKeyColumns("id");
        this.eventInsert = new SimpleJdbcInsert(jdbc)
                .withTableName("contact_report_event").usingGeneratedKeyColumns("id");
    }

    private static final RowMapper<ContactReport> REPORT_MAPPER = (rs, n) -> {
        ContactReport r = new ContactReport();
        r.setId(rs.getLong("id"));
        r.setStationId(rs.getLong("station_id"));
        r.setWindowId(rs.getLong("window_id"));
        r.setEntryId(rs.getLong("entry_id"));
        r.setStatus(ReportStatus.valueOf(rs.getString("status")));
        r.setRemark(rs.getString("remark"));
        r.setReportedAt(rs.getTimestamp("reported_at").toInstant());
        r.setCreatedAt(rs.getTimestamp("created_at").toInstant());
        return r;
    };

    public Optional<ContactReport> findByWindowForUpdate(long stationId, long windowId) {
        return jdbc.query("""
                         SELECT id, station_id, window_id, entry_id, status, remark,
                                reported_at, created_at
                         FROM contact_report
                         WHERE station_id = ? AND window_id = ?
                         FOR UPDATE""",
                REPORT_MAPPER, stationId, windowId).stream().findFirst();
    }

    /**
     * 尝试插入回报；并发重复回报由唯一索引拒绝并抛 {@link DuplicateKeyException}。
     */
    public long tryInsert(ContactReport report) throws DuplicateKeyException {
        var params = new java.util.LinkedHashMap<String, Object>();
        params.put("station_id", report.getStationId());
        params.put("window_id", report.getWindowId());
        params.put("entry_id", report.getEntryId());
        params.put("status", report.getStatus().name());
        params.put("remark", report.getRemark());
        params.put("reported_at", Timestamp.from(report.getReportedAt()));
        return reportInsert.executeAndReturnKey(params).longValue();
    }

    public long insertEvent(long stationId, long windowId, EventType type,
                            String payload, Instant createdAt) {
        var params = new java.util.LinkedHashMap<String, Object>();
        params.put("station_id", stationId);
        params.put("window_id", windowId);
        params.put("event_type", type.name());
        params.put("payload", payload);
        params.put("created_at", Timestamp.from(createdAt));
        return eventInsert.executeAndReturnKey(params).longValue();
    }

    public int countEvents(long stationId, long windowId, EventType type) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM contact_report_event WHERE station_id = ? AND window_id = ? AND event_type = ?",
                Integer.class, stationId, windowId, type.name());
        return count == null ? 0 : count;
    }

    public int countReports(long stationId, long windowId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM contact_report WHERE station_id = ? AND window_id = ?",
                Integer.class, stationId, windowId);
        return count == null ? 0 : count;
    }
}

