    /** 按日发布编排表；重复发布返回幂等成功。 */
    @PostMapping("/publish")
    public PublishResponseDto publish(@Valid @RequestBody PublishRequestDto dto) {
        return scheduleService.publish(dto.stationCode(), dto.dayKey());
    }

    /** 查询同站某日全部版本（旧版本可查）。 */
